@startuml

class Bookmaker {
  + placeBet(bettor: Bettor, race: Race, runner: Runner, amount: double, odds: double) : void
}

abstract class Person {}
class Bettor extends Person {
  + id : int
}
class Jockey extends Person {}

class Horse {
  + name : string
}

class Runner {
  + horse : Horse
  + jockey : Jockey
}

class Race {
  + runners : List<Runner>
  + winner : Runner
}

class Bet {
  + amount : double
  + odds : double
  + bettor : Bettor
  + race : Race
  + runner : Runner
}

Bookmaker "1" -- "*" Bet

@enduml

